 const svg=labCard(id,SVGO('0 0 640 420',`<rect width="640" height="420" fill="#f0fdf4"/>${U.map(([t,x,ic],k)=>`<g id="u${k}"><rect x="${x-56}" y="30" width="112" height="140" rx="16" fill="#fff" stroke="#86efac" stroke-width="3"/><g transform="translate(${x},92)">${ic}</g>${kPill(x,150,t,'#166534','#dcfce7',12)}</g>`).join('')}<g id="rfx"></g><g id="gl"></g><rect y="250" width="640" height="170" fill="#dcfce7"/><g id="tray"></g>`));
